#include <print>
#include <vector>

int main() {
    std::vector<std::vector<int>> d(3, std::vector<int>(4, 0));
    d[0][0] += 5;  d[0][2] -= 5;  d[2][0] -= 5;  d[2][2] += 5;
    d[0][1] -= 2;  d[0][3] += 2;
    d[2][1] += 2;  d[2][3] -= 2;
    for (int i = 0; i < 2; ++i)
        for (int j = 0; j < 3; ++j) {
            if (i > 0) d[i][j] += d[i-1][j];
            if (j > 0) d[i][j] += d[i][j-1];
            if (i > 0 && j > 0) d[i][j] -= d[i-1][j-1];
        }
    for (int i = 0; i < 2; ++i) std::println("{} {} {}", d[i][0], d[i][1], d[i][2]);
    return 0;
}
// 减 2 这块四个角全反：左上减 2，右上外和左下外加 2，右下外减 2

